    "blogPost.backToBlog": "Back to Blog",
    "blogPost.readTime": "read",
    "blogPost.minRemaining": "min left",
    "blogPost.relatedPosts": "Related Articles",
    "blogPost.toc.introduction": "Introduction",
    "blogPost.toc.content": "Article",
    "blogPost.toc.author": "About the Author",
    "blogPost.toc.newsletter": "Newsletter",
    "blogPost.toc.related": "Related Posts",
    "blogPost.share": "Share",
    "blogPost.ctaTitle": "Ready to Transform Your Business with AI?",
    "blogPost.ctaDesc": "Let us help you implement AI solutions that deliver real results. Schedule a free consultation today.",
    "blogPost.ctaButton": "Get in Touch",
